/* Current public narrative: pitch v8 takes priority over the technical appendix. */
const cpMoney = n => new Intl.NumberFormat('vi-VN',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const cpNumber = n => new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(n);
const cpLink = (url,label) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;
const cpButton = (href,label,secondary=false) => `<a class="cp-button${secondary?' cp-secondary':''}" href="${href}">${label}<span aria-hidden="true">→</span></a>`;
const cpKicker = s => `<p class="cp-kicker">${s}</p>`;
const cpHeader = (tag,title,desc) => `<header class="cp-heading">${cpKicker(tag)}<h1>${title}</h1><p>${desc}</p></header>`;
const cpSection = (tag,title,body) => `<section class="cp-section">${cpKicker(tag)}<h2>${title}</h2>${body}</section>`;
const cpNote = s => `<p class="cp-note">${s}</p>`;
const cpMetric = (n,label,small='') => `<div class="cp-metric"><strong>${n}</strong><span>${label}</span>${small?`<small>${small}</small>`:''}</div>`;
function cpIcon(name){const paths={camera:'M3 7h5l2-3h4l2 3h5v13H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',data:'M4 5c0-4 16-4 16 0s-16 4-16 0v14c0 4 16 4 16 0V5 M4 12c0 4 16 4 16 0',sim:'M12 2 22 7v10l-10 5-10-5V7z M2 7l10 5 10-5 M12 12v10',train:'M5 4h14v16H5z M8 8h8 M8 12h8 M8 16h5 M2 8h3 M19 8h3 M2 16h3 M19 16h3',gate:'M4 12l5 5L20 6 M3 22h18',robot:'M7 8h10v10H7z M12 8V3 M9 12h1 M14 12h1 M3 10v6 M21 10v6 M9 18v4 M15 18v4'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.data}"/></svg>`;}
function cpFigure(file,title,source,label){return `<figure class="cp-figure"><a href="assets/platform/${file}" target="_blank" rel="noopener" aria-label="Mở hình gốc: ${esc(title)}"><img src="assets/platform/${file}" alt="${esc(title)}" loading="lazy" width="1200"></a><figcaption><span>${title}</span>${cpLink(source,label+' · hình gốc')}</figcaption></figure>`;}
function cpWorkflow(){return `<section class="cp-flow" aria-labelledby="cp-flow-title"><div class="cp-flow-head"><div>${cpKicker('WORKFLOW CỦA PLATFORM')}<h2 id="cp-flow-title">Từ dữ liệu đến một policy được kiểm chứng</h2></div><span class="cp-status">Thiết kế đề xuất</span></div><p class="cp-hint">Chọn một bước để xem đầu vào, cách xử lý và đầu ra.</p><div class="cp-flow-steps" role="group" aria-label="Các bước workflow">${CURRENT_PLATFORM.steps.map((s,i)=>`<button type="button" data-cp-step="${i}" aria-pressed="${i===0}" aria-controls="cp-step-detail"><span class="cp-step-no">0${i+1}</span>${cpIcon(s.icon)}<strong>${s.title}</strong><small>${s.short}</small></button>`).join('')}</div><div class="cp-return">↶ Lỗi mới → kỹ sư duyệt can thiệp → cập nhật dữ liệu → huấn luyện và kiểm lại</div><div id="cp-step-detail" class="cp-step-detail" aria-live="polite">${cpStepDetail(0)}</div></section>`;}
function cpStepDetail(index){const s=CURRENT_PLATFORM.steps[index];return `<div class="cp-detail-label">0${index+1} / ${s.title}</div><div class="cp-detail-grid"><div><span>Đầu vào</span><p>${s.input}</p></div><div><span>Xử lý</span><p>${s.process}</p></div><div><span>Đầu ra</span><p>${s.output}</p></div></div><p class="cp-detail-gate">${cpIcon('gate')}${s.gate}</p>`;}
function cpOverview(){return `<section class="cp-hero"><div>${cpKicker('DENSO FACTORY HACKS 2026 · HUMANOID DATA FLYWHEEL')}<h1>Giảm công dạy humanoid.<br><em>Tích lũy kỹ năng sau mỗi lỗi.</em></h1><p>Tận dụng video thao tác người, teleop và mô phỏng để dạy một công đoạn tại DENSO Việt Nam. Mỗi lần cải thiện đều gắn với dữ liệu, policy và chi phí.</p><div class="cp-actions">${cpButton('#product','Xem platform hoạt động')}${cpButton('#validation','Một pipeline để chứng minh',true)}</div><span class="cp-hero-by">Đội ilovephysicalintelligence · Đề xuất PoC</span></div><div class="cp-hero-visual"><span class="cp-photo-label">MVP · Ψ₀ + SIMPLE / G1</span><img src="assets/platform/psi0-sim-data.png" alt="Figure gốc Ψ₀: các cảnh humanoid thao tác và tạo dữ liệu trong mô phỏng" width="1912" height="766"><div class="cp-hero-caption"><strong>Gắp → nâng → chuyển → đặt</strong><span>Task mô phỏng trước, robot thật nghiệm thu sau.</span>${cpLink(CURRENT_PLATFORM.sources.psi,'Nguồn hình: Ψ₀')}</div></div></section><div class="cp-metrics">${cpMetric('≥80%','Thành công / 50 lượt test','Mục tiêu PoC trong mô phỏng')}${cpMetric('−30%','Demo gốc, cùng chất lượng','200 → 140 là giả định đối chứng')}${cpMetric('$168.20','Tiết kiệm ròng / đợt','Kịch bản ước lượng, chưa đo DENSO')}</div>${cpSection('VẤN ĐỀ CẦN GIẢI QUYẾT','Robot lỗi. Kỹ sư cần biết sửa gì trước.',`<div class="cp-three"><article class="cp-plain"><span class="cp-index">01</span><h3>Gắp trượt</h3><p>Do dữ liệu thiếu tiếp xúc, hay controller và calibration?</p></article><article class="cp-plain"><span class="cp-index">02</span><h3>Đặt lệch khay</h3><p>Cần thu thêm mẫu nào, thay vì thu lại cả task?</p></article><article class="cp-plain"><span class="cp-index">03</span><h3>Đổi vị trí là lỗi</h3><p>Bổ sung tình huống trong sim có giảm được công thử lại?</p></article></div>${cpNote('Tình huống minh họa cho pilot gắp–đặt linh kiện vào khay. Task owner và baseline tại DENSO cần được xác nhận.')}`)}${cpWorkflow()}${cpSection('GIÁ TRỊ CHO DENSO','Bắt đầu từ một công đoạn. Giữ lại kỹ năng đã học.',`<div class="cp-three"><article class="cp-card"><h3>Dữ liệu sẵn có, chi phí thấp</h3><p>Kế thừa human prior, dùng dataset công khai và sim. Teleop tập trung vào hành động cần cho robot mục tiêu.</p></article><article class="cp-card"><h3>Cải thiện có bằng chứng</h3><p>Mỗi lỗi nối với can thiệp, release dữ liệu, policy và kết quả trước/sau.</p></article><article class="cp-card"><h3>Kiểm soát công kỹ thuật</h3><p>Đo công thu, QA, debug và GPU trên cùng chất lượng nghiệm thu.</p></article></div><div class="cp-actions">${cpButton('#business','Xem phép tính chi phí',true)}${cpButton('#team','Năng lực đội',true)}</div>`)}${cpNote('Trạng thái: có code/checkpoint/dataset tham khảo công khai và một reference MuJoCo kiểm logic gate. Chưa có kết quả Ψ₀ hoặc nghiệm thu robot thật của đội.')}`;}
function cpProduct(){return cpHeader('PLATFORM / WORKFLOW','Dữ liệu đúng lỗi.<br>Policy qua kiểm thử.','Điểm mới đề xuất nằm ở quy trình dạy humanoid theo công đoạn: chọn can thiệp, truy vết cải thiện, rồi quyết định cập nhật bằng chất lượng và chi phí.')+cpWorkflow()+`<div class="cp-extensions"><a href="#sources"><span>NHÁNH MỞ RỘNG DỮ LIỆU</span><strong>Video người raw → V2D → dữ liệu robot</strong></a><a href="#engine"><span>NHÁNH MỞ RỘNG ĐÁNH GIÁ</span><strong>Quan sát + action → DreamDojo → video tương lai</strong></a></div>`+cpSection('SO VỚI THU TELEOP VÀ TRAIN LẠI RIÊNG LẺ','Mỗi lần thử tạo thêm tài sản có thể dùng lại.',`<div class="cp-compare"><article><span>Quy trình rời rạc</span><h3>Lỗi → thu thêm → train lại</h3><p>Khó nối video lỗi với mẫu bổ sung và xác định đợt train có đáng công hay không.</p></article><article><span>Platform đề xuất</span><h3>Lỗi → chẩn đoán → can thiệp → kiểm lại</h3><p>Giữ lại dataset có phiên bản, policy nạp được, bộ test và sổ chi phí. Không đạt thì giữ baseline.</p></article></div>`)+cpSection('BÀN GIAO SAU MỘT VÒNG','Bốn đầu ra kiểm tra được',`<div class="cp-four">${['Dataset release + QA','Policy + cấu hình nạp lại','Kết quả A/B + bộ test','Công thu/QA/debug + GPU-h'].map((s,i)=>`<div class="cp-small-card"><b>0${i+1}</b><strong>${s}</strong></div>`).join('')}</div>${cpNote('Ψ₀, SIMPLE, V2D và DreamDojo là công nghệ có sẵn. Tích hợp và quy trình cải thiện là đóng góp đề xuất của đội; hiệu quả phải chứng minh bằng PoC.')}`);}
function cpSources(){return cpHeader('DỮ LIỆU / NGUỒN VÀ NHÃN','Bốn nguồn dữ liệu.<br>Bốn cách sử dụng rõ ràng.','Nguồn rẻ chỉ có ích khi biết nó cung cấp nhãn gì, học thành phần nào và cần kiểm tra gì trước khi dùng.')+`<div class="cp-four cp-data-types"><article class="cp-card">${cpIcon('camera')}<h2>Human ego</h2><p>Video từ góc nhìn người thao tác.</p><b>Học biểu diễn thao tác</b><small>RGB; pose/token nếu dataset có. PoC kế thừa prior qua checkpoint.</small></article><article class="cp-card">${cpIcon('camera')}<h2>Video người bên ngoài</h2><p>Video raw quay người và vật.</p><b>Tái dựng → grounding robot</b><small>Không mặc định là egocentric hoặc có robot action.</small></article><article class="cp-card">${cpIcon('robot')}<h2>Robot teleop</h2><p>Người điều khiển robot làm task.</p><b>Học hành động task</b><small>RGB + state + action đồng bộ, đúng robot/controller.</small></article><article class="cp-card">${cpIcon('sim')}<h2>Synthetic</h2><p>Dữ liệu sinh theo loại mô hình.</p><b>Sim có nhãn ≠ video dự đoán</b><small>Sim: state/action thực thi. World model: video tương lai.</small></article></div>`+cpDatasetExamples()+cpSection('VIDEO-TO-DATA / NVIDIA','Video người raw thành dữ liệu robot như thế nào?',cpFigure('v2d-overview.png','Từ human demonstration đến dữ liệu robot có cơ sở vật lý',CURRENT_PLATFORM.sources.v2d,'NVIDIA V2D')+`<div class="cp-three"><article class="cp-plain"><b>01 · Tái dựng</b><p>Clip → depth, mask, mesh, pose và quỹ đạo người–vật.</p></article><article class="cp-plain"><b>02 · Grounding</b><p>Retarget sang robot mục tiêu, thực thi và kiểm trong mô phỏng.</p></article><article class="cp-plain"><b>03 · Dataset</b><p>Ghi RGB/state/action, lọc theo QA và kết quả task.</p></article></div><div class="cp-stat-strip"><strong>1.215 <small>motion sequences</small></strong><strong>121.500 <small>robot episodes</small></strong><span>Dataset NVIDIA công bố · Sharpa · synthetic<br>${cpLink(CURRENT_PLATFORM.sources.v2dData,'Dataset card và phạm vi')}</span></div>${cpNote('Ví dụ về khả năng khai thác video người, không phải dataset G1 dùng ngay. Cần robot grounding, kiểm đơn vị/controller và QA; chi phí xử lý không bằng 0. Nhánh V2D là mở rộng, chưa tính trong ngân sách MVP Ψ₀ + SIMPLE.')}`)+cpSection('NGUỒN CHO POC','Chọn dữ liệu công khai đúng recipe',`<div class="cp-three"><article class="cp-card"><h3>EgoDex / human prior</h3><p>Video egocentric có tracking; kế thừa qua checkpoint Ψ₀ thay vì pretrain từ đầu.</p>${cpLink(CURRENT_PLATFORM.sources.ego,'EgoDex')}</article><article class="cp-card"><h3>SIMPLE / sim teleop</h3><p>Public robot demonstrations trong mô phỏng; chọn đúng task và kiểm schema.</p>${cpLink(CURRENT_PLATFORM.sources.psiData,'Dữ liệu SIMPLE')}</article><article class="cp-card"><h3>Rollout bổ sung</h3><p>Sinh trong sim quanh điều kiện còn thiếu. Chỉ đưa mẫu được chấp nhận vào task fine-tune.</p>${cpButton('#validation','Xem đối chứng A/B',true)}</article></div>`)+cpV2DTools();}
function cpLearning(){return cpHeader('TRAINING / Ψ₀','Human học biểu diễn.<br>Teleop dạy hành động.','Synthetic thực thi trong sim bổ sung tình huống cho task; phải dùng cùng schema robot và vượt QA.')+cpFigure('psi0-architecture.png','Architecture gốc của Ψ₀: VLM, action expert và controller',CURRENT_PLATFORM.sources.psi,'Ψ₀')+`<div class="cp-three cp-training"><article class="cp-card"><span class="cp-index">01 / HUMAN PRIOR</span><h2>Học thao tác từ người</h2><p>Video ego và nhãn pose/token hỗ trợ học biểu diễn. MVP kế thừa checkpoint đã học prior này.</p><b>Đầu ra: backbone có prior</b></article><article class="cp-card"><span class="cp-index">02 / ROBOT ACTIONS</span><h2>Học điều khiển task</h2><p>Ảnh, instruction và state robot → action chunks. Teleop dạy hành động; sim đạt QA bổ sung fine-tune.</p><b>Đầu ra: policy ứng viên</b></article><article class="cp-card"><span class="cp-index">03 / EXECUTION</span><h2>Robot thực thi</h2><p>Action chunks đi qua controller đúng cấu hình; ghi video/state/outcome để kiểm và phân tích lỗi.</p><b>Đầu ra: rollout + kết quả task</b></article></div>`+cpNote('Figure mô tả phương pháp của tác giả. Việc thêm synthetic theo lỗi là cấu hình thử nghiệm của đề xuất, chưa phải kết quả được paper chứng minh cho DENSO.')+cpSection('DỮ LIỆU → THÀNH PHẦN HỌC','Không dùng một loại nhãn cho mọi mục tiêu',table(['Dữ liệu','Dùng để học / kiểm gì?','Điều kiện'],[['Human RGB + pose/token','Biểu diễn thị giác–thao tác','Không coi pose người là lệnh khớp robot'],['Teleop RGB/state/action','Hành động của robot mục tiêu','Đồng bộ, đúng thứ tự khớp và controller'],['Rollout sim được chấp nhận','Fine-tune task / bao phủ tình huống','Cùng schema; root train/test tách riêng'],['Video DreamDojo dự đoán','Đánh giá / nghiên cứu world model','Không mặc định có joint state, lực hoặc contact']]))+`<div class="cp-actions">${cpButton('#validation','Recipe duy nhất cho PoC')}${cpButton('#engine','Input / output của DreamDojo',true)}</div>`;}
function cpEngine(){return cpHeader('WORLD MODEL / DREAMDOJO','Dự đoán video tương lai.<br>Action được đưa vào từ đầu.','DreamDojo là nhánh mở rộng cho đánh giá và lập kế hoạch. MVP Ψ₀ + SIMPLE không phụ thuộc vào nhánh này.')+`<div class="cp-io"><div><span>INPUT</span><h2>Quan sát đầu<br>+ action robot</h2><p>Chuỗi hành động điều kiện được cung cấp.</p></div><div class="cp-model">DreamDojo<br><small>World model</small></div><div><span>OUTPUT</span><h2>Video tương lai</h2><p>Chuỗi RGB dự đoán phản ứng theo action.</p></div></div>`+cpFigure('dreamdojo-overview.png','DreamDojo: human video pretraining, robot post-training, distillation và ứng dụng',CURRENT_PLATFORM.sources.dream,'DreamDojo')+cpSection('RECORD SYNTHETIC','Dataset nhánh này lưu được gì?',table(['Có thể lưu','Cần nguồn riêng'],[['Quan sát đầu + action điều kiện + future RGB','Joint state ground truth'],['Phiên bản generator, điều kiện sinh và lineage','Lực, contact và kết quả robot thật'],['Video dự đoán để nghiên cứu đánh giá policy','Nhãn action mới nếu chưa được cung cấp hoặc suy ra có kiểm chứng']])+cpNote('Video nhìn hợp lý không chứng minh task thực thi thành công. Nghiệm thu vẫn dùng simulator hoặc robot và scorer độc lập.'))+cpDreamDatasetExplanation()+`<div class="cp-actions">${cpButton('#sources','So với synthetic từ simulator',true)}${cpButton('#research','Nguồn phương pháp',true)}</div>`;}
function cpArchitecture(){return cpHeader('DATA FLYWHEEL','Một lỗi. Một can thiệp.<br>Một vòng kiểm chứng.','Chọn sửa hệ thống hay bổ sung dữ liệu trước khi bỏ thêm công thu mẫu và huấn luyện lại.')+`<section class="cp-flywheel"><div class="cp-fly-row"><div>${cpIcon('robot')}<strong>Chạy task</strong><small>Video / log / outcome</small></div><span>→</span><div class="cp-diamond"><strong>Lỗi ở đâu?</strong><small>Kỹ sư chẩn đoán</small></div><span>→</span><div class="cp-intervention"><strong>Kỹ sư duyệt can thiệp</strong><div class="cp-fault-branches"><span>Hệ thống<br><b>Controller / calibration</b></span><span>Dữ liệu<br><b>Teleop / sim đúng lỗi</b></span></div></div></div><div class="cp-down-link"><span>↓</span><small>Can thiệp được ghi lại → replay hoặc tạo candidate</small></div><div class="cp-fly-row"><div>${cpIcon('train')}<strong>QA & huấn luyện</strong><small>Release + replay</small></div><span>→</span><div>${cpIcon('gate')}<strong>Kiểm thử lại</strong><small>Cùng scorer và test</small></div><span>→</span><div class="cp-diamond"><strong>Tốt hơn?</strong><small>Quality + tổng chi phí</small></div></div><div class="cp-return">Đạt → cập nhật policy → chạy vòng tiếp theo &nbsp; | &nbsp; Chưa đạt → giữ baseline, phân tích lại</div></section><section class="cp-decision"><h2>Thử một tình huống lỗi</h2><p class="cp-hint">Minh họa logic quyết định; chưa phải hệ thống tự chẩn đoán đã triển khai.</p><div class="cp-choice" role="group" aria-label="Tình huống lỗi"><button data-cp-fault="binding" aria-pressed="true">Sai camera / calibration</button><button data-cp-fault="coverage" aria-pressed="false">Lỗi khi đổi vị trí vật</button><button data-cp-fault="unknown" aria-pressed="false">Chưa rõ nguyên nhân</button></div><div id="cp-fault-result" aria-live="polite">${cpFault('binding')}</div></section>`+cpSection('TRUY VẾT MỖI VÒNG','Giữ lại lý do policy được cập nhật',`<div class="cp-ledger">Lỗi <span>→</span> can thiệp kỹ sư duyệt <span>→</span> dataset release <span>→</span> policy version <span>→</span> test report <span>→</span> cost ledger</div>${cpNote('Không đưa lỗi do hệ thống vào bài toán thiếu dữ liệu. Không dùng test giữ riêng làm dữ liệu train của chính vòng đối chứng đó.')}`);}
function cpFault(kind){const data={binding:['Sửa hệ thống trước','Kiểm camera, đồng bộ, đơn vị, controller và calibration. Sửa cấu hình rồi replay baseline trước khi quyết định thu thêm dữ liệu.','Chưa có cơ sở mở một đợt synthetic hoặc fine-tune.'],coverage:['Bổ sung đúng điều kiện còn thiếu','Sau khi loại trừ lỗi hệ thống, chọn teleop hoặc rollout sim quanh vị trí vật/khay gây lỗi; QA và fine-tune candidate.','Giữ test độc lập; cập nhật chỉ khi đạt chất lượng và hiệu quả đã chốt.'],unknown:['Thu thêm bằng chứng','Giữ policy hiện tại. Kiểm log, ghi lại failure và bổ sung thông tin cần cho chẩn đoán.','Thiếu bằng chứng không đồng nghĩa thiếu demo.']};const d=data[kind];return `<h3>${d[0]}</h3><p>${d[1]}</p><strong>${d[2]}</strong>`;}
function cpValidation(){return cpHeader('POC / MỘT WORKFLOW ĐỐI CHỨNG','Ψ₀ + SIMPLE / G1.<br>Một task gắp–đặt.','Mục tiêu: chứng minh pipeline chạy được và kiểm tra liệu ít demo gốc hơn + sim có giữ chất lượng, giảm tổng công hay không.')+cpFigure('psi0-sim-data.png','Các cảnh và dữ liệu mô phỏng trong SIMPLE / Ψ₀',CURRENT_PLATFORM.sources.psi,'Ψ₀')+`<div class="cp-task"><span>Task công khai cần chạy</span><code>${CURRENT_PLATFORM.task}</code><p>Public sim teleop + checkpoint có human prior. Bài toán DENSO gắp linh kiện vào khay cần được ánh xạ và nghiệm thu riêng.</p></div><section class="cp-ab"><div class="cp-choice" role="group" aria-label="Cấu hình đối chứng"><button data-cp-ab="a" aria-pressed="true">A · Baseline</button><button data-cp-ab="b" aria-pressed="false">B · Candidate</button></div><div id="cp-ab-detail" aria-live="polite">${cpAB('a')}</div><div class="cp-ab-shared"><strong>Giữ giống nhau</strong><span>Checkpoint</span><span>Ngân sách train/eval</span><span>Scorer</span><span>Test giữ riêng</span></div></section><div class="cp-metrics">${cpMetric('≥80%','Full-task success','Mục tiêu ≥40/50 lượt mô phỏng giữ riêng')}${cpMetric('−30%','Demo gốc','Chỉ có ý nghĩa khi giữ cùng chất lượng')}${cpMetric('A ↔ B','Tổng chi phí','Thu + QA + debug + GPU + tích hợp')}</div>`+cpSection('CÁCH CHẠY ĐỂ TRÌNH BÀY BTC','Bằng chứng đầu-cuối cần tạo',`<ol class="cp-run-list"><li><b>Khóa task và dữ liệu.</b> Ghi revision code/checkpoint/dataset, robot/controller, train roots và test giữ riêng.</li><li><b>Chạy A.</b> Fine-tune bằng D demo teleop; lưu policy, video full task và chi phí.</li><li><b>Chạy B.</b> Chọn 0,7D roots; sinh sim từ train roots, lọc QA, fine-tune cùng ngân sách.</li><li><b>Test A/B.</b> Cùng điều kiện và scorer; báo full-task success, coverage, regression và công thực tế.</li><li><b>Chạy một vòng phản hồi.</b> Chọn một failure, duyệt can thiệp, tạo release mới, train và kiểm lại.</li></ol><div class="cp-source-links">${cpLink(CURRENT_PLATFORM.sources.psiCode,'Code Ψ₀')}${cpLink(CURRENT_PLATFORM.sources.simple,'Simulator SIMPLE')}${cpLink(CURRENT_PLATFORM.sources.psiData,'Public sim teleop')}${cpLink(CURRENT_PLATFORM.sources.ego,'Human prior / EgoDex')}</div>`)+cpNote('Đây là recipe chọn để chứng minh, không phải khẳng định thuật toán tốt nhất cho mọi task. Chưa benchmark VRAM, GPU-h, Ψ₀ hoặc robot thật. Bộ 50 lượt cho một PoC cần báo cả số lần đạt và điều kiện test; không tự chứng minh tương đương thống kê.')+`<div class="cp-actions">${cpButton('#examples','Reference đã chạy kiểm được gì?',true)}${cpButton('#business','Chi phí cho đúng PoC này')}</div>`;}
function cpAB(kind){return kind==='a'?`<div class="cp-ab-detail"><span class="cp-kicker">A / BASELINE</span><h2>D demo teleop</h2><p>Ví dụ ngân sách: <b>200 demo gốc được chấp nhận</b>, yield giả định 80% → 250 lượt thu. Fine-tune Ψ₀ trên task đã chọn.</p><b>Đầu ra: policy A + log + kết quả test + chi phí thực tế.</b></div>`:`<div class="cp-ab-detail"><span class="cp-kicker">B / CANDIDATE</span><h2>0,7D teleop + sim đạt QA</h2><p>Ví dụ ngân sách: <b>140 demo gốc được chấp nhận</b>, yield 80% → 175 lượt thu. Bổ sung rollout mô phỏng; số biến thể không được tính thành demo gốc mới.</p><b>Đầu ra: policy B + QA synthetic + cùng bộ báo cáo đối chứng.</b></div>`;}
function cpEvaluateCost(overrides={}){
 const a={...CURRENT_COST_MODEL.assumptions,...overrides};
 for(const [k,v] of Object.entries(a))if(typeof v!=='number'||!Number.isFinite(v)||v<0)throw new RangeError('Giả định phải là số không âm: '+k);
 if(a.yield<=0||a.yield>1||a.rootsAfter>a.rootsBefore)throw new RangeError('Yield phải >0 và ≤1; demo candidate không vượt baseline.');
 const cycles=overrides.cycles??144;if(!Number.isInteger(cycles))throw new RangeError('Số đợt phải là số nguyên.');
 const captureQA=r=>r/a.yield*(a.captureMin/60*a.operator+a.qaMin/60*a.engineer);
 const gpu=(a.mainA100h+a.evalA100h)*a.a100;
 const rows=[['Thu + QA teleop',captureQA(a.rootsBefore),captureQA(a.rootsAfter)],['Debug / phân tích lỗi',a.debugBefore*a.engineer,a.debugAfter*a.engineer],['GPU train, eval, sinh sim',gpu,gpu+a.sim4090h*a.rtx4090],['QA synthetic + tích hợp',0,(a.syntheticQAh+a.integrationh)*a.engineer],['Scratch storage / 1 tháng',a.storageBeforeGB*a.storage,a.storageAfterGB*a.storage]];
 const before=rows.reduce((s,r)=>s+r[1],0),after=rows.reduce((s,r)=>s+r[2],0),net=before-after;
 const setup=80*a.engineer+20*a.a100+200*a.storage,pilot=before+after,initial=setup+pilot,opex=48*a.engineer+500*12*a.storage;
 const steady=net*cycles-opex,firstYear=steady-initial;
 return {a,rows,before,after,net,setup,pilot,initial,opex,cycles,steady,firstYear,roi:initial?firstYear/initial*100:null,threshold:net>0?Math.floor((20000+opex)/net)+1:null,firstThreshold:net>0?Math.floor((20000+opex+initial)/net)+1:null};
}
function cpCostResults(c,eligible=true){return `<div class="cp-cost-total"><div><span>Baseline / đợt</span><strong>${cpMoney(c.before)}</strong></div><span>→</span><div><span>Đề xuất / đợt</span><strong>${cpMoney(c.after)}</strong></div><div class="${c.net>=0?'cp-saving':'cp-negative'}"><span>Ròng / đợt</span><strong>${eligible?cpMoney(c.net):'Chưa đủ điều kiện'}</strong></div></div>${table(['USD / một lần cải thiện task','Baseline','Đề xuất'],[...c.rows.map(r=>[r[0],cpMoney(r[1]),cpMoney(r[2])]),['<b>Tổng</b>',`<b>${cpMoney(c.before)}</b>`,`<b>${cpMoney(c.after)}</b>`]])}<div class="cp-metrics">${cpMetric(eligible?cpMoney(c.steady):'—','Năm ổn định',`${c.cycles} đợt đạt nghiệm thu, trừ OPEX chung`)}${cpMetric(eligible?cpMoney(c.firstYear):'—','Năm đầu','Trừ thêm đầu tư và pilot đối chứng')}${cpMetric(eligible&&c.roi!==null?cpNumber(c.roi)+'%':'—','ROI năm đầu','Lợi ích năm đầu / đầu tư ban đầu')}</div><p class="cp-note">${eligible?(c.net>0?`Để vượt $20.000: cần ≥${c.threshold} đợt/năm ổn định hoặc ≥${c.firstThreshold} đợt năm đầu, nếu giữ nguyên các giả định.`:'Kịch bản này không tạo tiết kiệm ròng mỗi đợt. Không có ngưỡng số đợt giúp vượt $20.000.'): 'Chưa đạt cùng chất lượng: không ghi nhận lợi ích hoặc ROI. Chi phí A/B vẫn phát sinh.'}</p><details class="cp-details"><summary>Đầu tư ban đầu, OPEX và công thức năm</summary><p>Setup: 80 giờ kỹ sư + 20 A100-h + 200 GB-tháng = <b>${cpMoney(c.setup)}</b>.<br>Pilot A + B = <b>${cpMoney(c.pilot)}</b>. Đầu tư ban đầu = <b>${cpMoney(c.initial)}</b>.<br>OPEX chung: 48 giờ kỹ sư/năm + 500 GB × 12 tháng = <b>${cpMoney(c.opex)}/năm</b>.</p><p>Năm ổn định = ròng/đợt × số đợt − OPEX chung.<br>Năm đầu = năm ổn định − đầu tư ban đầu. Số đợt sinh lợi không tính cặp pilot trong đầu tư.</p></details>`;}
function cpBusiness(){const c=cpEvaluateCost();return cpHeader('HIỆU QUẢ / ƯỚC LƯỢNG CÓ ĐIỀU KIỆN','Tiết kiệm công nào?<br>Tốn thêm chi phí nào?','So sánh một lần cải thiện task đạt cùng chất lượng. Giá GPU/storage có nguồn; khối lượng, đơn giá nhân công và mức giảm là giả định chưa đo tại DENSO.')+`<section class="cp-cost-controls"><div class="cp-flow-head"><h2>Thay giả định để kiểm tra kịch bản</h2><span class="cp-status">Không phải kết quả đo</span></div><form id="cp-cost-form" novalidate><div class="cp-form-grid"><label>Số đợt đạt nghiệm thu / năm<input name="cycles" type="number" value="144" min="0" max="10000" step="1" required></label><label>Giảm demo gốc (%)<input name="reduction" type="number" value="30" min="0" max="100" step="1" required></label><label>Debug candidate (giờ / đợt)<input name="debugAfter" type="number" value="10" min="0" max="10000" step="0.5" required></label><label>Operator (USD / giờ)<input name="operator" type="number" value="10" min="0" max="10000" step="0.5" required></label><label>Kỹ sư (USD / giờ)<input name="engineer" type="number" value="20" min="0" max="10000" step="0.5" required></label></div><div class="cp-cost-bottom"><label><input name="quality" type="checkbox" checked> Chỉ xét kịch bản đã đạt cùng chất lượng nghiệm thu</label><button type="reset" class="cp-reset">Về giả định của slide</button></div><p id="cp-cost-error" role="alert" hidden></p></form><p class="cp-hint">Baseline: 200 demo gốc, yield 80%, debug 20 giờ. Giả định chất lượng ở trên là điều kiện tính toán, không xác nhận PoC đã đạt.</p></section><section id="cp-cost-results" aria-live="polite" aria-label="Kết quả ước lượng chi phí">${cpCostResults(c)}</section>`+cpSection('R1 / R2 / A1','Nguồn giá và công thức baseline',`<div class="cp-three"><article class="cp-card"><b>R1 · GPU Runpod</b><p>A100 PCIe 80GB: <strong>$1.59/GPU-h</strong><br>RTX 4090: <strong>$0.74/GPU-h</strong></p>${cpLink(CURRENT_PLATFORM.sources.price,'Bảng giá Runpod')}<small>Giá lưu trong slide, kiểm 08/10/2026. Cần xác nhận khi thuê.</small></article><article class="cp-card"><b>R2 · Storage Runpod</b><p>Network volume dưới 1TB:<br><strong>$0.07/GB-tháng</strong></p>${cpLink(CURRENT_PLATFORM.sources.storage,'Cách tính storage')}<small>Scratch mỗi đợt giữ 1 tháng. Archive chung nằm trong OPEX năm.</small></article><article class="cp-card"><b>A1 · Giả định nội bộ mô hình</b><p>Operator $10/h; kỹ sư $20/h.<br>Yield 80%; thu/reset 6 phút; QA 3 phút/lượt.</p><small>Chưa là báo giá teleop/robotics hoặc baseline DENSO.</small></article></div><details class="cp-details"><summary>Xem phép tính từng khoản và những gì chưa đưa vào</summary><p>250/175 lượt thu = 200/140 demo gốc ÷ yield 80%. Thu/reset: 25/17,5h × $10 = $250/$175. QA: 12,5/8,75h × $20 = $250/$175. Debug: 20/10h × $20 = $400/$200.</p><p>Cả hai: 120h train + 20h eval A100 = $222.60. Candidate thêm: 20h RTX 4090 = $14.80; QA synthetic 6h + tích hợp 2h kỹ sư = $160; scratch tăng $7. Giảm công $350 − chi phí thêm $181.80 = <b>$168.20/đợt</b>.</p><p>GPU-h chưa benchmark; không suy ra model chắc chắn vừa VRAM hoặc chạy đủ trong ngân sách. Không pretrain human từ đầu, không triển khai V2D/DreamDojo trong PoC tính tiền này. Bổ sung mua robot/camera, adaptation, bảo mật, license, thuế và downtime nếu phát sinh.</p><p>72/144 đợt là kịch bản chưa xác nhận tại DENSO. Giá trị công tiết kiệm chỉ thành tiết kiệm tiền mặt khi thực sự giảm ngân sách hoặc có giá trị sử dụng công được xác nhận.</p></details><div class="cp-sensitive"><strong>Độ nhạy cần nhớ</strong><span>Không giảm debug → <b>−$31.80/đợt</b></span><span>Không giảm demo và debug → <b>−$181.80/đợt</b></span></div><a href="data/current-cost-model.json" download>Tải mô hình và giả định gốc ↓</a>`);}
function cpOutcomes(){return cpHeader('GIÁ TRỊ / ĐẦU RA VÀ KHẢ NĂNG MỞ RỘNG','Tích lũy kỹ năng theo task.<br>Mở rộng sau khi kiểm chứng.','Ưu tiên task mới trên cùng robot trước. Mỗi robot hoặc nhà máy mới cần dữ liệu, adapter/controller và nghiệm thu riêng.')+`<div class="cp-expansion"><article><span>01</span><h2>Cùng robot</h2><p>Thêm vị trí vật, khay và task tương tự; tái dùng QA, test và cách tính chi phí.</p></article><article><span>02</span><h2>Nhiều công đoạn</h2><p>Skill library có dataset release, policy và bộ test riêng; ghi rõ điều kiện sử dụng.</p></article><article><span>03</span><h2>Robot / nhà máy khác</h2><p>Kiểm camera, controller, calibration và dữ liệu target; pilot và nghiệm thu tại nơi nhận.</p></article></div>`+cpSection('TÀI SẢN PLATFORM DÙNG CHUNG','Tái dùng quy trình, kiểm riêng từng skill',`<div class="cp-four">${['Nguồn gốc & phiên bản dữ liệu','QA & schema','Đối chứng & regression','Sổ công & chi phí'].map(s=>`<div class="cp-small-card"><strong>${s}</strong></div>`).join('')}</div>${cpNote('Khả năng mở rộng là đề xuất. Chưa có bằng chứng triển khai nhiều task, nhiều robot hay nhiều nhà máy DENSO.')}`)+cpSection('ĐIỀU KIỆN BẮT ĐẦU PILOT','Bốn đầu vào cần phối hợp với DENSO',`<div class="cp-four">${['Một task và người phụ trách công đoạn','Video / log được phép sử dụng','Bảng công baseline: thu, QA, debug','Bộ test, quality, coverage, robot profile'].map((s,i)=>`<div class="cp-small-card"><b>0${i+1}</b><strong>${s}</strong></div>`).join('')}</div>`);}
function cpRoadmap(){return cpHeader('ROADMAP / MỐC NGHIỆM THU','Đi tiếp khi có bằng chứng.','Các bước theo đầu ra, không gắn thời hạn khi chưa kiểm dữ liệu, GPU và quyền tiếp cận robot.')+`<ol class="cp-roadmap">${CURRENT_PLATFORM.milestones.map((m,i)=>`<li><span class="cp-road-no">0${i+1}</span><div><h2>${m[0]}</h2><p><span>Bàn giao</span>${m[1]}</p><p><span>Điều kiện đi tiếp</span>${m[2]}</p></div></li>`).join('')}</ol><section class="cp-next-gate">${cpIcon('robot')}<div><h2>Sau PoC sim: nghiệm thu robot thật</h2><p>Controller và calibration phù hợp → kiểm an toàn, binding và task → đối chứng thực địa với DENSO.</p></div></section>`;}
function cpTeam(){return cpHeader('ĐỘI THỰC HIỆN','<span class="cp-team-name">ilovephysicalintelligence</span>','5 thành viên, 3 mảng chuyên môn để thực hiện PoC humanoid gắp–đặt. Thông tin năng lực do thành viên cung cấp; minh chứng đang bổ sung.')+`<div class="cp-team-grid">${CURRENT_PLATFORM.team.map((t,i)=>`<article class="cp-team-card"><div class="cp-team-top"><span>0${i+1}</span><b>${t.area}</b></div><h2>${t.names.map(esc).join('<br>')}</h2><p>${t.skills}</p>${t.affiliation?`<p class="cp-affiliation">${t.affiliation}</p>`:''}<div class="cp-team-output"><span>Đầu ra PoC dự kiến</span><strong>${t.output}</strong></div><p class="cp-proof-pending">${t.status}</p><small>${t.proof}</small></article>`).join('')}</div><div class="cp-team-owner"><strong>Đầu mối chốt công đoạn và nghiệm thu: Dương Đình Hiếu</strong><p>Phối hợp với task owner DENSO. Người phụ trách xác nhận bảng công và hiệu quả cần chốt khi bắt đầu pilot.</p></div>`+cpSection('MINH CHỨNG / KHÔNG CẦN GITHUB CÔNG KHAI','Một link kiểm tra được cho mỗi mảng',`<div class="cp-three"><article class="cp-plain"><b>Robot Learning</b><p>Video demo VLA/RL; cấu hình model/task, log và kết quả; ghi phần Hiếu trực tiếp làm.</p></article><article class="cp-plain"><b>Simulation</b><p>Video cảnh chạy task; mô tả robot/controller, dữ liệu xuất và phần Hưng/Châu đảm nhiệm.</p></article><article class="cp-plain"><b>Data / Platform</b><p>Mẫu dữ liệu trước/sau; schema, báo cáo QA và phần Long/Thông thực hiện.</p></article></div>${cpNote('Có thể dùng thư mục Drive/OneDrive hoặc trang video với quyền xem. Mỗi minh chứng nên có tên người, task, cách chạy và giới hạn. Website chưa gắn link vì chưa được cung cấp.')}`);}
function cpResearch(){return cpHeader('NGUỒN / PHƯƠNG PHÁP ĐƯỢC SỬ DỤNG','Một recipe PoC.<br>Hai hướng mở rộng.','Hình và phương pháp thuộc các tác giả gốc. Kết quả của paper không được coi là kết quả đo của đội.')+`<div class="cp-three"><article class="cp-card"><span class="cp-status">Recipe PoC</span><h2>Ψ₀ + SIMPLE</h2><p>Human prior → robot actions → task fine-tune. Dùng checkpoint và sim teleop cho đối chứng.</p>${cpLink(CURRENT_PLATFORM.sources.psi,'Trang paper')}${cpButton('#learning','Xem training',true)}</article><article class="cp-card"><span class="cp-status">Mở rộng dữ liệu</span><h2>NVIDIA V2D</h2><p>Video người → tái dựng → grounding → dữ liệu robot có cơ sở vật lý.</p>${cpLink(CURRENT_PLATFORM.sources.v2d,'Toolkit và tài liệu')}${cpButton('#sources','Xem input / output',true)}</article><article class="cp-card"><span class="cp-status">Mở rộng đánh giá</span><h2>DreamDojo</h2><p>Quan sát đầu + action điều kiện → video tương lai. Không tự sinh mọi nhãn vật lý.</p>${cpLink(CURRENT_PLATFORM.sources.dream,'Trang paper')}${cpButton('#engine','Xem architecture',true)}</article></div>`+cpNote('Sự tồn tại của code, dataset và figure chứng minh có nền tảng để triển khai. Chưa chứng minh tích hợp chạy được hoặc tiết kiệm chi phí trong task của DENSO.')+cpSection('PHẠM VI BẰNG CHỨNG','Ba mức cần phân biệt',table(['Mức','Hiện có','Không suy ra'],[['Nguồn công khai','Paper, code, checkpoint, dataset','Đội đã tái lập kết quả tác giả'],['Reference của đội','MuJoCo thu nhỏ kiểm logic QA/gate','Ψ₀ hoặc humanoid thật đã đạt'],['PoC đề xuất','Recipe A/B và target rõ','Đã đạt target hay ROI thực tế']]))+`<div class="cp-actions">${cpLink(CURRENT_PLATFORM.sources.v2dRepo,'Repo V2D')}${cpLink(CURRENT_PLATFORM.sources.v2dTutorial,'CoRL tutorial')}</div>`;}
function cpExamples(){return cpHeader('REFERENCE / PHẠM VI ĐÃ KIỂM','Bản chạy nhỏ kiểm logic gate.','Bản ghi MuJoCo này dùng state lý tưởng, predictor 4D và grasp weld. Chưa kiểm Ψ₀, human transfer hoặc robot thật.')+cpNote('S 12/12, C 0/12 là kết quả reference thu nhỏ. Không dùng số này thay target ≥80%/50 của PoC humanoid.')+engineeringExampleMarkup()+`<div class="cp-actions">${cpButton('#validation','Quay lại PoC cần chứng minh')}</div>`;}
function renderCurrentPlatform(id){const routes={overview:cpOverview,product:cpProduct,sources:cpSources,learning:cpLearning,engine:cpEngine,architecture:cpArchitecture,validation:cpValidation,business:cpBusiness,outcomes:cpOutcomes,roadmap:cpRoadmap,team:cpTeam,research:cpResearch,examples:cpExamples};return routes[id]?`<div class="cp-page" data-current-presentation="pitch-v8">${routes[id]()}</div>`:null;}
function initCurrentPlatform(signal){
 main.querySelectorAll('[data-cp-step]').forEach(b=>b.addEventListener('click',()=>{main.querySelectorAll('[data-cp-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelector('#cp-step-detail').innerHTML=cpStepDetail(Number(b.dataset.cpStep));},{signal}));
 main.querySelectorAll('[data-cp-fault]').forEach(b=>b.addEventListener('click',()=>{main.querySelectorAll('[data-cp-fault]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelector('#cp-fault-result').innerHTML=cpFault(b.dataset.cpFault);},{signal}));
 main.querySelectorAll('[data-cp-ab]').forEach(b=>b.addEventListener('click',()=>{main.querySelectorAll('[data-cp-ab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelector('#cp-ab-detail').innerHTML=cpAB(b.dataset.cpAb);},{signal}));
 const form=main.querySelector('#cp-cost-form');if(form){const result=main.querySelector('#cp-cost-results'),error=main.querySelector('#cp-cost-error');function update(){error.hidden=true;if(!form.checkValidity()){error.textContent='Nhập đủ giá trị trong giới hạn; số đợt/năm phải là số nguyên không âm.';error.hidden=false;result.innerHTML='<p class="cp-note">Chưa thể tính: cần sửa giả định không hợp lệ.</p>';return;}try{const f=form.elements,c=cpEvaluateCost({cycles:Number(f.cycles.value),rootsAfter:CURRENT_COST_MODEL.assumptions.rootsBefore*(1-Number(f.reduction.value)/100),debugAfter:Number(f.debugAfter.value),operator:Number(f.operator.value),engineer:Number(f.engineer.value)});result.innerHTML=cpCostResults(c,f.quality.checked);}catch(e){error.textContent=e.message;error.hidden=false;result.innerHTML='';}}
 form.addEventListener('input',update,{signal});form.addEventListener('submit',e=>e.preventDefault(),{signal});form.addEventListener('reset',e=>{e.preventDefault();for(const input of form.querySelectorAll('input')){if(input.type==='checkbox')input.checked=input.defaultChecked;else input.value=input.defaultValue;}update();},{signal});}
 if(main.querySelector('#engineering-example'))initEngineering(signal);
 if(main.querySelector('#cp-dataset-gallery'))initCPDatasetGallery(signal);
}

function cpDatasetExamples(){return cpSection('EXAMPLE / DỮ LIỆU CÓ THỂ XEM VÀ KIỂM','Xem video. Đọc tín hiệu thật.',`<section id="cp-dataset-gallery" class="cp-dataset-gallery"><p class="cp-hint">Chọn một mẫu để xem video/hình và dữ liệu đi kèm. Đây là nguồn công khai của tác giả, không phải dữ liệu DENSO hoặc kết quả PoC của đội.</p><div class="cp-dataset-choices" role="group" aria-label="Chọn ví dụ dataset">${CURRENT_PLATFORM.datasetExamples.map((d,i)=>`<button type="button" data-cp-dataset="${d.id}" aria-pressed="${i===0}" aria-controls="cp-dataset-body"><strong>${d.label}</strong><small>${d.kind}</small></button>`).join('')}</div><div id="cp-dataset-body">${cpDatasetBody('human')}</div></section>`);}
function cpDatasetBody(id){
 const preview=(name,label)=>`<a href="data/${name}.json" target="_blank" rel="noopener">${label} · JSON ↗</a>`;
 if(id==='human')return `<div class="cp-example-intro"><h3>HumanEgo / Aria · serve_bread_000</h3><p>Human ego RGB và 1.002 tracking rows của tay. Wrist pose là tín hiệu người, chưa phải robot joint action.</p></div><div class="inspector-layout">${media('humanTracking')}<section class="panel inspector" id="human-inspector"><p>Đang đọc mẫu tracking…</p></section></div>${cpNote('Tracking thiếu phải giữ null + validity mask, không coi [0,0,0] là pose thật. Preview không giả đồng bộ từng frame video–tracking. HumanEgo data: CC BY-NC 4.0; cần kiểm quyền dùng khi triển khai thương mại.')}<div class="cp-source-links">${preview('humanego-hands','Tracking đã trích')}${cpLink(MEDIA.humanTracking.source,'Dataset nguồn')}</div><details class="cp-details"><summary>Xem thêm video minh họa cách thu human ego</summary>${media('human')}<p>Video collection minh họa riêng của tác giả, không ghép thành cặp thời gian với tracking serve_bread_000 ở trên.</p></details>`;
 if(id==='g1')return `<div class="cp-example-intro"><h3>Unitree G1 / Dex3 · toasted bread</h3><p>Teleop robot thật. Episode 0: 620 frames, 30fps, 28 state và 28 action values/frame. Chọn khớp hoặc frame để đọc dữ liệu.</p></div><div class="inspector-layout">${media('g1')}<section class="panel inspector" id="robot-inspector"><p>Đang đọc state/action…</p></section></div>${cpNote('Đây là mẫu G1 thật để hiểu schema, không phải task SIMPLE đang chọn cho PoC. Video pin revision; numeric preview Rows API chưa đối chiếu bitwise với pinned parquet. Chưa xác minh căn từng frame video; chưa có force/contact trong preview.')}<div class="cp-source-links">${preview('g1-episode-0','620 rows state/action')}${cpLink(MEDIA.g1.source,'Dataset Unitree')}</div>`;
 if(id==='gr1')return `<div class="cp-example-intro"><h3>RoboCasa GR1 · đặt chai vào tủ, đóng cửa</h3><p>Demonstration humanoid trong mô phỏng. RGB ego, 29 state và 29 action dimensions; episode 0 có 376 frames ở 20fps.</p></div><div class="inspector-layout">${media('gr1').replace('Task household có waist unlocked; khác task khay fixed-torso của proposal.','Ví dụ GR1 trong sim; không phải dataset G1/SIMPLE của PoC.')}<section class="panel inspector" id="gr1-inspector"><p>Đang đọc 6 rows từ parquet…</p></section></div>${cpNote('Numeric trích từ parquet pin revision; không gọi đây là real-robot teleop hoặc rollout policy của đội. Preview row và player được chọn độc lập. Nguồn NVIDIA/RoboCasa CC BY-NC 4.0.')}<div class="cp-source-links">${preview('gr1-preview','Metadata + 6 rows')}${cpLink(MEDIA.gr1.source,'Dataset GR1')}</div>`;
 if(id==='libero')return `<div class="cp-example-intro"><h3>LIBERO / Panda · đặt hai cốc lên đĩa</h3><p>Demonstration trong sim. Episode 0: 214 frames ở 10fps; state 8 chiều, action 7 chiều. Không phải humanoid.</p></div><div class="inspector-layout">${media('libero')}<section class="panel inspector" id="libero-inspector"><p>Đang đọc numeric preview…</p></section></div>${cpNote('Chỉ 6 rows đầu trong inspector; không tự chạy số theo video. Numeric Rows API chưa đối chiếu bitwise với pinned parquet. Số chiều khác nhau cần mapping/controller phù hợp trước khi dùng cho robot khác.')}<div class="cp-source-links">${preview('libero-preview','Metadata + 6 rows')}${cpLink(MEDIA.libero.source,'Dataset LIBERO')}</div>`;
 if(id==='mimicgen')return `<div class="cp-example-intro"><h3>MimicGen · từ seed demonstrations đến biến thể trong sim</h3><p>Xem seed và các tình huống được tạo thêm. Nhãn robot đến từ rollout thực thi trong simulator, cần lọc thành công và QA.</p></div><div class="media-grid">${media('simSeed')}${media('sim')}</div>${cpNote('Ví dụ của tác giả MimicGen để hiểu logic synthetic physics; không phải kết quả đã chạy Ψ₀/SIMPLE của đội. Biến thể không được đếm thành các demo gốc độc lập.')}`;
 if(id==='dreamgen')return `<div class="cp-example-intro"><h3>DreamGen · video được sinh và policy rollout</h3><p>Hai video là hai loại bằng chứng khác nhau. DreamGen là phương pháp riêng, không phải DreamDojo.</p></div><div class="media-grid">${media('dream')}${media('dreamPolicy')}</div>${cpNote('Không suy ra video synthetic tự chứa đủ state/action/force/contact. Các kết quả thuộc tác giả; không phải rollout DENSO hoặc bằng chứng DreamDojo đã tạo dataset hoàn chỉnh.')}<div class="cp-actions">${cpButton('#engine','DreamDojo sinh được những gì?',true)}</div>`;
 throw new RangeError('Ví dụ dataset không tồn tại.');
}
function cpV2DTools(){return cpSection('TOOLKIT SỬ DỤNG / NVIDIA VIDEO TO DATA','Các công cụ để biến video thành dữ liệu robot',`<div class="cp-source-links cp-tool-links">${cpLink(CURRENT_PLATFORM.sources.v2dRepo,'GitHub · nvidia-isaac/video_to_data')}${cpLink(CURRENT_PLATFORM.sources.v2dTutorial,'CoRL tutorial · From Human Videos to Dexterous Robot Capability')}</div>${table(['Bước','Tool / thành phần','Input → output'],CURRENT_PLATFORM.v2dTooling)}<div class="cp-three"><article class="cp-plain"><b>Kiểm video và hình học</b><p>Clip đúng thao tác; depth/mask/mesh/pose hợp lý, scale và thời gian khớp.</p></article><article class="cp-plain"><b>Kiểm khả thi robot</b><p>Retarget đúng embodiment, support/contact hợp lý; rollout vượt scorer.</p></article><article class="cp-plain"><b>Kiểm dataset huấn luyện</b><p>Đúng action/state schema, có nguồn gốc, tách train/test và lưu QA.</p></article></div><details class="cp-details"><summary>Đọc đúng vai trò repo và tutorial</summary><p>Repo cung cấp các gói ingestion, reconstruction và robotic grounding. Chạy từng stage, kiểm artifact rồi mới nối pipeline. Tutorial tổ chức tương tự: video truy xuất được → reconstruction hợp lý → robot-facing assets/motion → policy training/evaluation trong Isaac Lab.</p><p>Trang tutorial mô tả hướng laptop inspection, chạy GPU và precomputed artifacts; danh sách materials có mục sẽ công bố sau tutorial. Không mặc định mọi notebook/artifact đã tải được. Đối chiếu README và pin revision trước khi triển khai.</p><p>Đây là nhánh mở rộng V2D. Mô hình chi phí và recipe PoC hiện hành vẫn là Ψ₀ + SIMPLE; không cộng ngầm pipeline V2D vào ngân sách.</p></details>`);}
function cpDreamDatasetExplanation(){return cpSection('CÂU HỎI / SYNTHETIC DATA ĐẦY ĐỦ?','Có thể tạo dữ liệu để học, nhưng cần xác định nhãn.',`<div class="cp-compare"><article><span>DREAMDOJO TỰ SINH</span><h3>Video phản ứng theo action</h3><p>Quan sát đầu + action từ teleop/policy → chuỗi RGB dự đoán. Có thể lưu cặp RGB/action điều kiện để nghiên cứu augmentation hoặc đánh giá.</p></article><article><span>CẦN BỔ SUNG CHO POLICY</span><h3>State, nhãn vật lý và QA</h3><p>Không tự có joint state kế tiếp, force/contact hoặc reward/success được đo. Policy cần state phải có mô hình trạng thái, simulator hoặc phép đo phù hợp.</p></article></div>${cpNote('Action điều kiện không phải action mới được DreamDojo tự gán nhãn từ một video người bất kỳ. Post-training cần dữ liệu robot mục tiêu; latent action học từ video người không đồng nghĩa lệnh khớp robot.')}<div class="cp-ledger">Ví dụ + action có sẵn <span>→</span> DreamDojo dự đoán RGB <span>→</span> thêm state/nhãn còn thiếu <span>→</span> QA <span>→</span> thử train policy <span>→</span> test trong sim/robot</div><p class="cp-hint">Đây là thiết kế tích hợp đề xuất, không phải tính năng tạo dataset hoàn chỉnh được repo bảo đảm. RGB/action tổng hợp có thể hữu ích, nhưng cải thiện robot learning phải kiểm thực nghiệm. Paper thử policy một camera không dùng proprioceptive state để đánh giá trong world model; không tự nhiên hỗ trợ multi-view.</p><div class="cp-source-links">${cpLink(CURRENT_PLATFORM.sources.dreamCode,'DreamDojo · code chính thức')}${cpLink(CURRENT_PLATFORM.sources.dreamPaper,'Paper · phương pháp và downstream applications')}</div>`);}
function initCPDatasetGallery(signal){
 const root=main.querySelector('#cp-dataset-gallery'),body=root.querySelector('#cp-dataset-body');let child=new AbortController();signal.addEventListener('abort',()=>child.abort(),{once:true});
 function show(id){child.abort();child=new AbortController();root.querySelectorAll('[data-cp-dataset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cpDataset===id)));body.innerHTML=cpDatasetBody(id);initMedia(body,child.signal);if(id==='human'||id==='g1')initSamples(child.signal);if(id==='gr1')initGR1(child.signal);if(id==='libero')initLibero(child.signal);}
 root.querySelectorAll('[data-cp-dataset]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.cpDataset),{signal}));show('human');
}
